const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo(resolve, reject);
  });
}

function maskS2(img) {
  var scl = img.select('SCL');
  var mask = scl.neq(0)
    .and(scl.neq(1))
    .and(scl.neq(3))
    .and(scl.neq(8))
    .and(scl.neq(9))
    .and(scl.neq(10))
    .and(scl.neq(11));
  return img.updateMask(mask).select(['B3', 'B11']).toFloat();
}

function maskLandsat(img) {
  var qa = img.select('QA_PIXEL');
  var mask = qa.bitwiseAnd(1 << 0).eq(0) // fill
    .and(qa.bitwiseAnd(1 << 1).eq(0))    // dilated cloud
    .and(qa.bitwiseAnd(1 << 2).eq(0))    // cirrus
    .and(qa.bitwiseAnd(1 << 3).eq(0))    // cloud
    .and(qa.bitwiseAnd(1 << 4).eq(0))    // cloud shadow
    .and(qa.bitwiseAnd(1 << 5).eq(0));   // snow
  var scaled = img.select(['SR_B3','SR_B6']).multiply(0.0000275).add(-0.2)
                  .rename(['B3','B11']).toFloat();
  return scaled.updateMask(mask);
}

function s2Collection(start, end, geom) {
  return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geom)
    .filterDate(start, end)
    .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 90))
    .map(maskS2);
}

function landsatCollection(start, end, geom) {
  var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(geom).filterDate(start, end);
  var l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(geom).filterDate(start, end);
  return l8.merge(l9).map(maskLandsat);
}

async function analyzeWindow(dateStr, geom, scale, padDays) {
  var date = ee.Date(dateStr);
  var start = date.advance(-padDays, 'day');
  var end = date.advance(padDays + 1, 'day');
  var src = 'S2';
  var coll = s2Collection(start, end, geom);
  var size = await getInfoAsync(coll.size());
  var usedPad = padDays;

  if (size === 0) {
    src = 'Landsat';
    coll = landsatCollection(start, end, geom);
    size = await getInfoAsync(coll.size());
    if (size === 0) {
      // widen window
      usedPad = 10;
      start = date.advance(-usedPad, 'day');
      end = date.advance(usedPad + 1, 'day');
      src = 'S2';
      coll = s2Collection(start, end, geom);
      size = await getInfoAsync(coll.size());
      if (size === 0) {
        src = 'Landsat';
        coll = landsatCollection(start, end, geom);
        size = await getInfoAsync(coll.size());
        if (size === 0) {
          return {status: 'C1'};
        }
      }
    }
  }

  var mosaic = coll.median().clip(geom);
  var valid = await getInfoAsync(mosaic.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 2
  }).get('B3'));
  if (valid === null) return {status: 'C3'};
  if (valid === 0) return {status: 'C2'};

  var mndwi = mosaic.expression('(G - S) / (G + S)', {
    G: mosaic.select('B3'),
    S: mosaic.select('B11')
  }).rename('mndwi');

  var waterMask = mndwi.gt(0.2).updateMask(mosaic.select('B3').mask());
  var waterPix = await getInfoAsync(waterMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 2
  }).get('mndwi'));
  if (waterPix === null) return {status: 'C3'};

  return {
    status: 'OK',
    source: src,
    imgs: size,
    usedPad: usedPad,
    validPix: valid,
    waterPix: waterPix
  };
}

async function runAnalysis() {
  try {
    // Geometry: shared border of Craighead and Jackson counties, AR, buffered 1000 m
    var counties = ee.FeatureCollection('TIGER/2018/Counties')
      .filter(ee.Filter.eq('STATEFP', '05'));
    var craig = counties.filter(ee.Filter.eq('NAME', 'Craighead')).first();
    var jack = counties.filter(ee.Filter.eq('NAME', 'Jackson')).first();
    var craigGeom = ee.Feature(craig).geometry();
    var jackGeom = ee.Feature(jack).geometry();
    var sharedLine = craigGeom.boundary().intersection(jackGeom.boundary(), ee.ErrorMargin(1));
    var roi = sharedLine.buffer(1000);

    var SCALE = 30;
    var totalPix = await getInfoAsync(ee.Image(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: SCALE,
      maxPixels: 1e9,
      tileScale: 2
    }).get('constant'));

    console.log(`ROI total pixels @${SCALE}m: ${totalPix}`);

    var y2023 = await analyzeWindow('2023-04-13', roi, SCALE, 3);
    if (y2023.status !== 'OK') {
      console.log(`2023 Status: ${y2023.status}`);
      console.log(y2023.status);
      return;
    }
    var cloud2023 = 100 * (1 - y2023.validPix / totalPix);
    var areaHa2023 = y2023.waterPix * (SCALE * SCALE) / 10000.0;
    console.log(`2023 Source:${y2023.source} imgs:${y2023.imgs} win:±${y2023.usedPad}d Valid:${y2023.validPix}/${totalPix} Cloud:${cloud2023.toFixed(1)}% WaterPix:${y2023.waterPix} Area_ha:${areaHa2023.toFixed(1)}`);

    var y2025 = await analyzeWindow('2025-04-13', roi, SCALE, 3);
    if (y2025.status !== 'OK') {
      console.log(`2025 Status: ${y2025.status}`);
      console.log(y2025.status);
      return;
    }
    var cloud2025 = 100 * (1 - y2025.validPix / totalPix);
    var areaHa2025 = y2025.waterPix * (SCALE * SCALE) / 10000.0;
    console.log(`2025 Source:${y2025.source} imgs:${y2025.imgs} win:±${y2025.usedPad}d Valid:${y2025.validPix}/${totalPix} Cloud:${cloud2025.toFixed(1)}% WaterPix:${y2025.waterPix} Area_ha:${areaHa2025.toFixed(1)}`);

    // Decision
    if (!isFinite(areaHa2023) || !isFinite(areaHa2025)) {
      console.log('C3');
      return;
    }
    var ans = areaHa2025 > areaHa2023 ? 'A' : 'B';
    console.log(ans);
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
